import React, { useState } from 'react'
import { useSelector, useDispatch } from 'react-redux'
import { logout } from '../redux/actions/authAction'
import { GLOBALTYPES } from '../redux/actions/globalTypes'
import { useTranslation } from 'react-i18next'
import { Link } from 'react-router-dom'
 
import Avatar from './Avatar'


import Card from 'react-bootstrap/Card'
import {
  Navbar,
  Container,
  NavDropdown,
  Offcanvas,
  Button,
  Dropdown,
} from 'react-bootstrap'
import { FaUserCircle } from 'react-icons/fa'


const Navbar2 = () => {
  const { auth, theme } = useSelector((state) => state)
  const dispatch = useDispatch()
  const { languageReducer } = useSelector(state => state);
  const { t } = useTranslation('navbar');  
  const lang = languageReducer.language || 'en'; 
  const [showDrawer, setShowDrawer] = useState(false)

  const openStatusModal = () => {
    dispatch({ type: GLOBALTYPES.STATUS, payload: true })
  }

  const handleLogout = () => {
    dispatch(logout())
  }

  const toggleTheme = () => {
    dispatch({ type: GLOBALTYPES.THEME, payload: !theme })
  }

  const handleCloseDrawer = () => setShowDrawer(false)
  const handleShowDrawer = () => setShowDrawer(true)

  return (
    <>
      <Navbar expand="lg" className="navbar bg-body-tertiary mb-2 shadow-sm px-3">
        <Container fluid className="align-items-center">
          <div className="d-flex align-items-center">
            <div className="d-block d-lg-none">
              {auth.user ? (
                <NavDropdown
                  id="user-dropdown-mobile"
                  align="start"
                  title={
                    <div className="d-flex dropdown-avatar">
                      <Avatar src={auth.user.avatar} size="medium-avatar" />
                    </div>
                  }
                >
                  <NavDropdown.Item onClick={openStatusModal}>
                    {t('addPost', { lng: lang })}
                  </NavDropdown.Item>
                  <NavDropdown.Item as={Link} to="/informacionaplicacion" onClick={handleCloseDrawer}>
                    {t('appInfo', { lng: lang })}
                  </NavDropdown.Item>
                  <NavDropdown.Item as={Link} to="/message" onClick={handleCloseDrawer}>
                    {t('adminChat', { lng: lang })}
                  </NavDropdown.Item>
                  <NavDropdown.Item as={Link} to="/administration/roles" onClick={handleCloseDrawer}>
                    {t('roles', { lng: lang })}
                  </NavDropdown.Item>
                  {auth.user.role === 'admin' && (
                    <>
                      <NavDropdown.Item as={Link} to="/administration/users/reportuser" onClick={handleCloseDrawer}>
                        {t('reportedUsers', { lng: lang })}
                      </NavDropdown.Item>
                      <NavDropdown.Item as={Link} to="/administration/homepostspendientes" onClick={handleCloseDrawer}>
                        {t('pendingPosts', { lng: lang })}
                      </NavDropdown.Item>
                      <NavDropdown.Item as={Link} to="/administration/usersaction" onClick={handleCloseDrawer}>
                        {t('userActions', { lng: lang })}
                      </NavDropdown.Item>
                      <NavDropdown.Item as={Link} to="/administration/usersedicion" onClick={handleCloseDrawer}>
                        {t('userEditing', { lng: lang })}
                      </NavDropdown.Item>
                      <NavDropdown.Item as={Link} to="/administration/listadeusuariosbloqueadoss" onClick={handleCloseDrawer}>
                        {t('blockedUsers', { lng: lang })}
                      </NavDropdown.Item>
                    </>
                  )}
                  <NavDropdown.Item as={Link} to={`/profile/${auth.user._id}`} onClick={handleCloseDrawer}>
                    {t('profile', { lng: lang })}
                  </NavDropdown.Item>
                  <NavDropdown.Item onClick={toggleTheme}>
                    {theme ? t('lightMode', { lng: lang }) : t('darkMode', { lng: lang })}
                  </NavDropdown.Item>
                  <NavDropdown.Divider />
                  <NavDropdown.Item onClick={handleLogout}>
                    {t('logout', { lng: lang })}
                  </NavDropdown.Item>
                </NavDropdown>
              ) : (
                <NavDropdown
                  align="start"
                  title={<FaUserCircle size={25} />}
                  id="guest-dropdown-mobile"
                >
                  <NavDropdown.Item as={Link} to="/login">
                    {t('login', { lng: lang })}
                  </NavDropdown.Item>
                  <NavDropdown.Item as={Link} to="/register">
                    {t('register', { lng: lang })}
                  </NavDropdown.Item>
                </NavDropdown>
              )}
            </div>

            <Navbar.Brand href="/" className="py-2 me-0 me-lg-3 d-none d-lg-block">
              <Card.Title>{t('appName', { lng: lang })}</Card.Title>
            </Navbar.Brand>
          </div>

          <div className="d-flex align-items-center justify-content-center gap-3">
          
 
         

            <Dropdown>
              <Dropdown.Toggle variant="secondary" id="custom-dropdown">
                {t('navbar:options', { lng: lang })}
              </Dropdown.Toggle>
              <Dropdown.Menu>
                <Dropdown.Item as={Link} to="/custompage1">
                  {t('navbar:customPage1', { lng: lang })}
                </Dropdown.Item>
                <Dropdown.Item as={Link} to="/custompage2">
                  {t('navbar:customPage2', { lng: lang })}
                </Dropdown.Item>
              </Dropdown.Menu>
            </Dropdown>
 
            <Button className="d-lg-none" onClick={handleShowDrawer} size="sm" variant="outline-primary">
              {t('navbar:menu', { lng: lang })}
            </Button>

            <div className="d-none d-lg-block">
              {auth.user ? (
                <NavDropdown
                  id="user-dropdown"
                  align="end"
                  title={
                    <div className="d-flex dropdown-avatar">
                      <Avatar src={auth.user.avatar} size="medium-avatar" />
                    </div>
                  }
                >
                  <NavDropdown.Item onClick={openStatusModal}>
                    {t('navbar:addPost', { lng: lang })}
                  </NavDropdown.Item>
                  <NavDropdown.Item as={Link} to="/informacionaplicacion">
                    {t('navbar:appInfo', { lng: lang })}
                  </NavDropdown.Item>
                  <NavDropdown.Item as={Link} to="/message">
                    {t('navbar:adminChat', { lng: lang })}
                  </NavDropdown.Item>
                  <NavDropdown.Item as={Link} to="/administration/roles">
                    {t('navbar:roles', { lng: lang })}
                  </NavDropdown.Item>
                  {auth.user.role === 'admin' && (
                    <>
                      <NavDropdown.Item as={Link} to="/administration/users/reportuser">
                        {t('navbar:reportedUsers', { lng: lang })}
                      </NavDropdown.Item>
                      <NavDropdown.Item as={Link} to="/administration/homepostspendientes">
                        {t('navbar:pendingPosts', { lng: lang })}
                      </NavDropdown.Item>
                      <NavDropdown.Item as={Link} to="/administration/usersaction">
                        {t('navbar:userActions', { lng: lang })}
                      </NavDropdown.Item>
                      <NavDropdown.Item as={Link} to="/administration/usersedicion">
                        {t('navbar:userEditing', { lng: lang })}
                      </NavDropdown.Item>
                      <NavDropdown.Item as={Link} to="/administration/listadeusuariosbloqueadoss">
                        {t('navbar:blockedUsers', { lng: lang })}
                      </NavDropdown.Item>
                    </>
                  )}
                  <NavDropdown.Item as={Link} to={`/profile/${auth.user._id}`}>
                    {t('navbar:profile', { lng: lang })}
                  </NavDropdown.Item>
                  <NavDropdown.Item onClick={toggleTheme}>
                    {theme ? t('navbar:lightMode', { lng: lang }) : t('navbar:darkMode', { lng: lang })}
                  </NavDropdown.Item>
                  <NavDropdown.Divider />
                  <NavDropdown.Item onClick={handleLogout}>
                    {t('navbar:logout', { lng: lang })}
                  </NavDropdown.Item>
                </NavDropdown>
              ) : (
                <NavDropdown
                  align="end"
                  title={<FaUserCircle size={25} />}
                  id="guest-dropdown-desktop"
                >
                  <NavDropdown.Item as={Link} to="/login">
                    {t('navbar:login', { lng: lang })}
                  </NavDropdown.Item>
                  <NavDropdown.Item as={Link} to="/register">
                    {t('navbar:register', { lng: lang })}
                  </NavDropdown.Item>
                </NavDropdown>
              )}
            </div>
          </div>
        </Container>
      </Navbar>

      <Offcanvas show={showDrawer} onHide={handleCloseDrawer} placement="start">
        <Offcanvas.Header closeButton>
          <Offcanvas.Title>{t('navbar:menu', { lng: lang })}</Offcanvas.Title>
        </Offcanvas.Header>
        <Offcanvas.Body style={{ maxHeight: '60vh', overflowY: 'auto' }}>
          <Button variant="link" as={Link} to="/" onClick={handleCloseDrawer}>
            {t('navbar:home', { lng: lang })}
          </Button>
          <br />
          <Button variant="link" as={Link} to="/profile" onClick={handleCloseDrawer}>
            {t('navbar:profile', { lng: lang })}
          </Button>
        </Offcanvas.Body>
      </Offcanvas>


    </>
  )
}

export default Navbar2
